"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 situation text (plan 3.1): the one text every text-reading system gets at a decision point.

Inputs per decision point: the unit's meta row (sources with times, the assistant's turns as spoken under teacher
forcing), the transcripts of every speech segment that ended before the point (Whisper, keyed by segment id), the
speaker tags (user / not the user, from the speaker-ID model), and the detected sounds (class, start, end, peak score;
from the shared detector over the audio before the point, listed when the peak is at least 0.2). Nothing from the gold
labels and no scoring mask enters the text: the questions asked depend only on what the system can know (is the
assistant talking, did a line just end).

Variants: full (L1, L2, L3, T, B1-strong, B2, B3), no_sounds (T0: every detector line removed, history included) and
line_only (T0-single: only the line just said and its tag). ideal_inputs (added 2026-11-16 for the reference B2-ideal,
plan 6.5) replaces the perceived inputs with the true ones; build() itself is unchanged.
"""

IDEAL_CLASSES = ("phone", "doorbell", "knock", "call", "footsteps", "door", "cabinet", "decoy")
IDEAL_MERGE_S = 0.3          # as the detector's runs (p1v4_feats.MERGE_GAP_S): footstep pieces become one sound

SOUND_NAMES = {"phone": "phone ringing", "doorbell": "doorbell", "knock": "knocking", "call": "someone calling out",
               "footsteps": "footsteps", "door": "a door opening or closing", "cabinet": "a cupboard or drawer",
               "decoy": "a household sound"}


def _fmt_t(x):
    return f"{x:.1f} s"


def ideal_inputs(row, k, transcripts):
    """Perfect perception at point k (B2-ideal, plan 6.5): (transcripts, tags, sounds) for build().
    - Speech: the scripted words. A segment still going at the point gets the share of its words spoken so far
      (proportional to the time elapsed), so nothing after the point leaks. A real TV or radio recording has no script
      and keeps the given (Whisper) transcript.
    - Speakers: the true speaker (the user, or not the user: visitor, TV voice, TV recording).
    - Sounds: every event clip that started before the point with its true class and times (cut at the point),
      confidence 1.0; pieces of the same class closer than 0.3 s are merged, as the detector's runs are."""
    t = row["points"][k]["t"]
    tr, tags = {}, {}
    for s in row["sources"]:
        if s["kind"] not in ("speech", "tvfile") or s["start"] >= t:
            continue
        ongoing = s["end"] > t
        key = f"{s['id']}@{k}" if ongoing else s["id"]
        if s["kind"] == "tvfile":
            if key in transcripts:
                tr[key] = transcripts[key]
        else:
            words = s["text"].split()
            n = int(len(words) * (t - s["start"]) / (s["end"] - s["start"])) if ongoing else len(words)
            tr[key] = " ".join(words[:n])
        tags[key] = "user" if s["kind"] == "speech" and s.get("who") == "user" else "other"
    clips = sorted((s["cls"], s["start"], min(s["end"], t)) for s in row["sources"]
                   if s["kind"] == "clip" and s.get("cls") in IDEAL_CLASSES and s["start"] < t)
    sounds = []
    for cls, a, b in clips:
        if sounds and sounds[-1][0] == cls and a - sounds[-1][2] < IDEAL_MERGE_S:
            sounds[-1][2] = max(sounds[-1][2], b)
        else:
            sounds.append([cls, a, b, 1.0])
    return tr, tags, [tuple(x) for x in sorted(sounds, key=lambda x: (x[1], x[0]))]


def build(row, k, transcripts, tags, sounds, variant="full"):
    """row: meta row of the unit version; k: point index; transcripts/tags: {segment id: text / "user"|"other"};
    sounds: [(class, start, end, peak)] detected before the point. Times are seconds from the unit start."""
    p = row["points"][k]
    t = p["t"]
    lines = []
    talking = [a for a in row["assistant"] if a["start"] <= t - 1e-3 < a["end"]]
    if variant != "line_only":
        if talking:
            a = talking[0]
            lines.append(f"The assistant is talking right now (for {_fmt_t(t - a['start'])}). It is saying: "
                         f"«{a['text']}»")
        else:
            done = [a for a in row["assistant"] if a["end"] <= t]
            if done:
                lines.append(f"The assistant is not talking; it has been silent for {_fmt_t(t - done[-1]['end'])}.")
            else:
                lines.append("The assistant is not talking and has not spoken yet in this session.")
        hist = []
        for s in row["sources"]:                       # finished segments, and the part before t of ongoing ones
            if s["kind"] in ("speech", "tvfile") and s["id"] != p.get("line") and s["start"] < t:
                ongoing = s["end"] > t
                key = f"{s['id']}@{k}" if ongoing else s["id"]
                if key in transcripts:
                    who = "the user" if tags.get(key, tags.get(s["id"])) == "user" else "a voice that is not the user"
                    hist.append((s["start"], f"[{_fmt_t(s['start'])}] {who}: «{transcripts[key]}»"
                                 + (" (still speaking)" if ongoing else "")))
        for a in row["assistant"]:
            if a["start"] < t and a not in talking:
                said = a["text"] if a["end"] >= a["full_end"] - 1e-6 else a["text"] + " (cut off)"
                hist.append((a["start"], f"[{_fmt_t(a['start'])}] the assistant: «{said}»"))
        if variant == "full":
            for cls, s0, s1, peak in sounds:
                if s0 < t:
                    name = SOUND_NAMES.get(cls, cls)
                    hist.append((s0, f"[{_fmt_t(s0)}] detected sound: {name}, {_fmt_t(s0)} to {_fmt_t(min(s1, t))} "
                                     f"(confidence {peak:.2f})"))
        if hist:
            lines.append("Earlier, oldest first:")
            lines += [h for _, h in sorted(hist)]
    if p.get("line"):
        who = "the user" if tags.get(p["line"]) == "user" else "a voice that is not the user"
        lines.append(f"Just now {who} said: «{transcripts.get(p['line'], '')}»")
    else:
        lines.append("Nobody has just finished speaking.")
    asks = []
    # S is asked where the assistant is talking, and at points the renderer marks as S points (kind S or RS): in a few
    # S-react units the assistant finishes its sentence just after the user's line ends, before the decision point
    # (2026-11-15: 1 dev, 15 train points); these keep their S question, so every system answers what is scored.
    if talking or p.get("assistant_speaking") or p.get("kind") in ("S", "RS"):
        asks.append("S: should the assistant STOP or CONTINUE talking?")
    if p.get("line"):
        asks.append("R: should the assistant RESPOND to the line just said, or NOT?")
    return "\n".join(lines), asks
